('20260415005400112751', '(복지부) 26년 정신건강 심리상담 바우처사업', '바우처', '우울·불안 등 정서적 어려움으로 인해 심리상담이 필요한 국민에게 전문적인 심리상담 서비스를 제공합니다.', '□ 서비스 내용
