('20251231005400212058', '인공지능 리터러시 운영', '교육지원', '도민을 위한 AI 기초역량 강화 교육', 'AI 활용에 관심있는 도민 대상 AI 기초교육, 찾아가는 AI 시군특강, 도민강사 양성 교육 운영', '21', '경기도', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-10-01', '2025-12-31', FALSE);

