('20250918005400211762', '경남 웹툰캠퍼스 운영', '교육지원', '웹툰 전문교육, 입주실 및 창작 지원으로 지역 인재 양성 및 웹툰산업 활성화, 웹툰 페스티벌 개최를 통한 웹툰 산업 확산 및 향유 기회 마련', '○ 도내 청소년, 일반인 및 예비·기성 웹툰작가
○ 단계별 전문 웹툰교육 운영 및 창작 지원, 작가·기업 입주실 운영 등', '21', '문화산업과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250918005400211761', '경남글로벌게임센터 운영', '교육지원', '글로벌 게임 산업의 중심지로 변화하는 혁신적인 허브 조성, 경남의 게임 산업 생태계 강화 및 글로벌 네트워크 확장을 통한 지속 가능한 성장 체계 구축', '○ 경남글로벌게임센터 운영, 게임산업 육성
○ 인큐베이팅 지원, 게임 제작 지원, 게임산업 유통 지원, 인재 양성 지원', '21', '문화산업과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250918005400211759', '그린 스타트업 타운 조성', '교육지원', '낙후된 도심기능을 창업, 벤처 중심으로 회복시키기 위해 도시재생뉴딜사업과 연계한 친환경 스타트업 타운 조성', '복합허브센터 신축(8,000㎡) 및 공학2호관 일부 리모델링(769㎡)', '21', '창업지원과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250918005400211758', '청년 창업아카데미 운영', '교육지원', '권역별 청년 유동인구가 많고, 접근성과 창업 인프라 환경이 우수한 곳을 창업 거점으로 운영하여 지역 간 창업 지원 불균형 해소', '○ (예비) 창업가
○ 경남 동부권(양산, 김해, 밀양) 청년 창업 아카데미 조성에 따른 사업 및 운영비 지원
  - 청년 창업아카데미 입주기업 선발 및 맞춤형 창업기업 지원사업 추진
  - 경남 동부지역 창업문화 및 창업 네트워크 확산 프로그램 운영
  - 민간 참여 협업사업 추진', '21', '창업지원과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250918005400211757', '대학 특화 청년창업 활성화 지원', '교육지원', '도내 대학 보유 공간, 장비, 연구성과 등을 활용한 대학별 특화 비즈니스 모델 정립 및 체계적인 실전형 청년 창업 지원, 대학별 창업 특화 분야의 우수 창업기획자(액셀러레이터) 지원으로 체계적인 청년 창업가 육성 기반 마련', '○ 19 ~ 39세 도내 청년 창업자(업력 7년 미만)
○ 대학별 특화 창업분야 육성 지원 및 액셀러레이팅
  - 사업화, 투자유치, 대학 내 공간 연계 창업공간 지원
  - 창업기획자(액셀러레이터)를 통한 액셀러레이팅, 데모데이 개최', '21', '창업지원과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-01-01', '2025-01-31', FALSE),
('20250918005400211756', '주력산업 상생희망공제 지원', '보조금,중소기업', '협업을 통한 기업 청년 핵심인력 장기재직 지원으로 중소기업 성장 촉진과 경쟁력 강화로 지역 인구 유입 및 지역 주도형 청년일자리 창출', '○ (사업대상)
  - (기업) 도내 주력산업(항공, 방산 등, 제조업 포함)을 영위하는 중소기업
  - (청년) 해당 기업에 종사하는 18 ~ 45세 재직자
○ (사업내용)  
  - 도내 주력산업 중소기업에 재직 중인 청년이 5년간 만기 재직한 경우 청년지원금 지원
     * 만기금(2,880만원/5년) = 도(720만원) + 기업(1,440만원) + 청년(720만원)', '22', '청년정책과', 18, 45, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-01-01', '2025-01-31', FALSE),
('20250918005400211755', '청년 면접정장 무료 대여', '장기미취업청년', '청년 실업률 증가 및 취업 준비기간의 장기화로 청년들에게 소요되는 구직 과정의 과중한 경제적 부담 경감', '○ 18 ~ 39세 취업준비생 및 구직자(도내 주소를 둔 청년)
○ 구직 청년에 대한 면접정장 무료 대여(3박 4일, 연 5회/인)', '22', '청년정책과', 18, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250918005400211754', '청년일자리 위드유 운영', '장기미취업청년', '다양한 취·창업 사업연계 및 청년 커뮤니티 활동 지원 등 종합서비스를 제공하고 청년 수요에 맞는 맞춤형 지원을 강화', '○ 18 ~ 39세 예비창업가 및 미취업 청년 
○ 청년 취·창업 원스톱 서비스 지원 및 네트워크 공간 제공
  - 청년 취·창업 활동 지원 공간 대여
  - 취·창업 활동 지원 온·오프라인 프로그램 운영
  - 경남 귀환청년 프로젝트 전담창구 운영 및 청년사업 소개', '22', '산업인력과', 18, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250917005400211753', '도시재생 청년인재 양성', '장기미취업청년', '도시재생 전문인력 양성 및 시군 도시재생지원센터, 지역대학과 연계하여 도시재생 지구 활성화를 위한 청년일자리 창출에 기여', '○ (사업대상) 기타(도시재생에 관심 있는 도내 청년 및 대학생)
  - (연령기준) 19 ~ 39세
  - (기타조건) 도시재생 공동이용시설 활성화를 위해 도내 주요 대학과 연계하여 현장실습학기제, 일경험수련생으로 청년인턴 운영
○ 도시재생대학(기초·심화과정)+청년인턴+도시재생사 양성', '22', '도시정책과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-01-01', '2025-01-31', FALSE),
('20250917005400211752', '청년어업인 귀어 인턴 지원', '장기미취업청년', '귀어 취업 희망 청년층을 대상으로 선도어가, 어업법인 등 실무연수를 통한 영어 정착 동기 부여로 어업부문 신규 인력 유입', '○ 지원대상
  - (실무연수 인턴) 시군이 추천하는 일정 조건을 갖춘 영어조합법인 또는 어업회사법인, 선도 어가 등 우수 어업경영체 * (대상 인턴) 18 ~ 49세의 미취업자 및 청년 귀어 희망인
   - (어촌계 인턴) 어촌계의 정관에 따라 신규로 가입한 어촌계원(준어촌계원 포함)
○ 주요내용
  - (실무연수 인턴) 영어 취업 희망 청년층을 대상으로 채용대상자 등에 인턴(실무연수)으로 근무 시 월 보수의 일부 지원
  - (어촌계 인턴) 어촌계 신규 가입 시 가입비 일부 지원', '22', '어촌발전과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250917005400211751', '청년 일경험 지원', '장기미취업청년', '청년 일경험을 통해 직무탐색 및 직무역량 강화', '○ 미취업 청년(18 ~ 39세) : 사업기간 동안 해당 지자체 주민등록 유지
○ 청년 일경험 수당 및 기업멘토수당 지원', '22', '산업인력과', 18, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250917005400211750', '기업 채용 연계 청년일자리 지원', '장기미취업청년', '도-기업-대학(특성화고) 간 협약을 통한 기업 맞춤형 청년 인재 취업 지원을 통한 구인·구직 미스매치 해소', '○ 현장실습학기제 및 인력양성사업 참여기업
○ 채용장려금 : 월 60만원(1인) 최대 12개월 지원, 기업당 5인 이내  
○ 환경개선금 : 기업당 최대 2,000만원 지원
○ 주거정착금 : 월 30만원(1인) 이내 최대 12개월 지원 * 청년 직접 지원', '22', '산업인력과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE);

