('20250917005400211748', '문화콘텐츠분야 청년일자리 지원', '장기미취업청년', '콘텐츠산업 수도권 집중화로 청년인구 유출 및 지역 불균형 심화, 청년들의 일자리 수요가 높은 지역콘텐츠 기업의 전략적 육성 및 산학연 연계 현장 중심의 기업이 원하는 전문인력 양성 필요', '○ 도내 문화콘텐츠기업
○ 신규 청년 정규직 채용 인건비 지원
