○ 청년 인건비, 창업지원금 지급, 취·창업 컨설팅 지원', '22', '산업인력과', 18, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-01-01', '2025-01-31', FALSE),
('20250917005400211746', '경남 청년 멀티미디어 디자이너 육성 지원', '장기미취업청년', '가상현실 관련 기술 제품 디자인, 게임물, 영상콘텐츠 등 디지털 콘텐츠를 활용한 정보미디어에 대한 역량을 갖춘 디자이너 육성', '○ 미취업 청년(18 ~ 39세)
○ 정보통신업종, 디자인전문회사
○ (기업) 청년 인건비 지원(2년, 인당 월 200만원, 인건비 10% 기업 자부담)  
○ (청년) 교통비(월 10만원), 역량강화지원비(연 60만원), 주거임차비(월 30만원), 3년차 인센티브(1년, 분기별 250만원) 지원, 멀티미디어 직무 기본·심화교육 실시', '22', '경제기업과', 18, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-01-01', '2025-01-31', FALSE),
('20250917005400211745', '경남 청년 농식품수출 마케터 지원', '장기미취업청년', '도내 농식품 수출 기업들의 포스트 코로나 시대 적응 및 수출 경쟁력 제고를 위한 청년 마케팅 인력 지원', '○ 도내 해당 지자체 주민등록 19 ~ 39세 청년
○ 인건비 : 수출농단 및 업체 청년 채용 지원(기준 : 2,000천원/인/월)
○ 기타지원금 : 교육, 현장활동 등 지원(기준 : 250천원/인/월)
○ 자율지원비 : 주거비 및 교통비 등 지원(기준 : 400천원/인/월)
○ 인센티브 : 정규직 전환(유지)에 대한 지원(기준 : 2,500천원/인/분기)', '22', '농식품유통과', 19, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-01-01', '2025-01-31', FALSE),
('20250917005400211744', '경남 청년 메타버스 UX 디자이너 육성 지원', '장기미취업청년', '메타버스 서비스 확산의 핵심 요소인 UX의 청년 디자이너 육성 및 전문기업 일자리 제공', '○ 미취업 청년(18 ~ 39세)
○ 도내 중소기업 : 메타버스 UX 디자인 분야
