('20250623005400111109', '청년 등 기업가 대상 중소기업 법률 서비스 지원', '중소기업', '지원단 변호사가 중소기업을 위한 법률서비스를 제공할 경우 법률지원단이 비용 일부 지원', '2009년 1월부터 운영된 「9988 중소기업 법률지원단」과 2015년 4월부터 운영된 「창조경제혁신센터 법률지원단」이 2024년 6월부터 「법무부 중소기업 법률지원단」으로 통합되어 운영되고 있다. 이 지원단은 중소기업과 소상공인을 대상으로 법률자문과 소송지원을 제공하며, 일반 기업에는 자문 최대 100만 원, 소송 최대 200만 원까지 지원한다. 다만 2025년 6월 2일부터는 「1인 창조기업 육성에 관한 법률 시행령」 제2조 제3항에 따른 청년기업의 경우에는 자문 최대 200만 원, 소송 최대 300만 원으로 한도가 상향된다. 청년기업이란 39세 이하 청년이 대표권 있는 임원으로 등기되어 있는 회사(공동대표의 경우 청년이 비청년보다 더 많은 의결권을 보유한 경우) 또는 청년 개인사업자를 말한다. 현재 법률지원단에는 약 102명의 변호사가 활동 중이다.', '22', '상사법무과', 0, 0, TRUE, '0043001', 0, 0, NULL, '1. ｢중소기업기본법｣ 제2조에 따른 “중소기업”
