('20250618005400111003', '전세사기 피해 예방 및 지원 강화', '주거지원', '주택가격 상승기에 전세반환보증 악용, 임차인 정보 부족 등으로 전세사기 피해가 현실화되어 피해를 입은 임차인, 특히 청년 등 주거취약계층의 주거안정 도모를 목적으로 함', '전세사기피해자에게 경·공매 절차 및 조세 징수 등에 관한 특례를 부여하고, 저리·대환대출 등 금융지원, 우선매수권 양도를 통한 매입임대 등 주거지원 등을 제공함으로써 청년층의 주거 안정을 도모', '13', '국토교통부', 0, 0, TRUE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250618005400111001', '청년 자산형성 지원(청년도약계좌)', '보조금', '만기 5년 동안 매월 70만원 한도 내에서 자유롭게 납입 가능한 정부지원형 적금상품으로 청년의 중장기 자산형성을 지원합니다.', '□ 청년도약계좌는 매월 가입신청할 수 있도록 운영 (청년도약계좌의 비과세 혜택이 ''25.12.31일부로 일몰됨에 따라 상품 신규 가입신청 중단)
