('20250328005400210671', '서귀포시 대학생·청년 아르바이트 사업', '장기미취업청년', '대학생 및 대학교를 다니지 않는 일반 청년에게 동하계 방학동안 직·간접적인 시정 업무 체험과 사회경험을 통한 진로탐색 및 학비마련의 기회를 제공하고자 함', '본청 및 읍면동주민센터 등 배치부서 업무 특성에 따른 행정업무 지원
