('20250228005400210574', '2025년 순창군 대학 진학 축하금 지원', '교육지원,보조금', '순창에 주소를 두고 고등학교를 졸업 또는 고졸 검정고시 합격 후 3년이내 대학교에 진학한 자에게 경제적 부담을 덜어주기 위해 축하금 지원', '지원대상 : 관내·관외고등학교를 졸업 또는 고졸 검정고시 합격 후 3년이내 대학교에 진학한 자
