('20250123005400110395', '구직자ㆍ기업 도약보장 패키지', '맞춤형상담서비스', '□ 인구·산업구조 변화, 취업·채용 형태 다양화, 일에 대한 인식 변화, 온라인·디지털 서비스 확산 등 고용서비스 여건 변화에 대응 필요', '□ 구직자 : ①잡케어(Job Care) 기반 개인별 직무역량 및 노동시장 정보 분석 제공, ②1:1 심층 상담을 통한 경력개발 로드맵 설계, ③경력설계를 위한 맞춤형 서비스 연계 및 프로그램 제공 등
