('20250113005400210195', '사회적경제 청년혁신가 지원사업', '장기미취업청년', '사회적경제 사업장 실무인력 양성 및 청년 일자리 창출', '사회적경제 사업장에 필요한 실무인력 양성 및 교육훈련 제공을 통해 지역에 정착할 수 있는 지속가능한 청년일자리 창출', '22', '전북특별자치도', 18, 39, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-01-01', '2025-12-31', FALSE),
('20250113005400210193', '전북특별자치도 청년마음건강센터 운영', '맞춤형상담서비스', '청년 맞춤형 정신건강 서비스 제공', '정신건강의 어려움을 겪는 청년을 발굴하여 적절한 조기개입을 통한 정신질환 예방 및 맞춤형 정신건강 서비스 제공으로 회복 지원', '33', '전북특별자치도', 19, 34, FALSE, '0043001', 0, 0, NULL, NULL, NULL, NULL, NULL, FALSE),
('20250113005400110192', '청년임업인 특성화교육', '교육지원', '청년임업인 네트워킹을 통한 학습그룹 발굴, 그룹별 수요맞춤형 임산물 재배기술 교육, 현장실증형 장기교육(체류형, 출퇴근형 등), 임업 우수사례지 견학 등', '&lt; 청년임업인 특성화 교육 &gt;
1. 사업목적 : 청년층을 대상으로 현장 실증형, 네트워킹 중심 특성화 교육 제공으로 임업분야 정착 지원 및 전문임업인으로 육성
2. 교육대상 : 임업에 종사하고자 하는 예비임업인(일반인, 청년), 임업에 종사하고 있는 청년임업인 등
3. 교육내용 : 청년의 특성 및 교육 수요를 반영한 맞춤형 교육 제공
  - 청년 네트워킹 교육 : 청년 네트워킹을 통한 학습그룹 발굴, 청년간 소통 및 교류기회 제공, 자체 네트워크 형성 지원
  - 청년학습그룹 : 기관 중심의 교육(집합교육 등)을 탈피, 청년 간 자율학습그룹 조직 및 문제해결을 위한 자생적 교육 운영 지원
  - 현장실증형 교육 : 우수한 수준으로 임업에 종사하고 있는 전문임업인의 유휴 부지를 청년임업인 현장교육장소로 대여, 교육생 대상 신품목, 유망품목 시험재배 및 밀착형 컨설팅 기회 제공
  - 임산물 재배기술교육 : 수준별(초중급/고급) 청년임업인을 위한 임산물 재배 기술교육 및 밀착 컨설팅', '21', '사유림경영소득과', 19, 50, FALSE, '0043001', 0, 0, NULL, NULL, NULL, '2025-02-17', '2025-10-31', FALSE),
('20250113005400210190', '2025년 상반기 경기도 학자금 대출이자 지원', '대출,신용회복', '한국장학재단에서 대출받은 학자금의 직전 6개월간 발생한 이자 지원', '○ 본인 또는 직계존속 1명 이상이 공고일 기준 1년 이상 경기도에 계속 거주한 대학(원) 재학&middot;휴학생 및 미취업 졸업생 대상
