('20250113005400210188', '국토부 청년월세 한시 특별지원사업', '보조금', '신청일 기준 창원시에 주민등록이 되어 있는 19세 ~ 34세 이하 청년으로 부모와 별도 거주하는 무주택자의 월세 지원', '월 최대 20만원씩 12개월(회) 동안 매월 분할 지원', '12', '창원시', 19, 34, FALSE, '0043003', 0, 0, '(청년가구)중위소득 60% 이하 / (원가구)중위소득 100%', NULL, NULL, '2024-02-26', '2025-02-25', FALSE),
('20250113005400210184', '용인청년 창업지원주택', '공공임대주택', '경기주택도시공사가 신축 주택을 매입하여 용인청년 1인 창조기업인에게 직‧주 혼합 소호(SOHO)형 주택을 주변시세의 30~50% 이하로 임대', '○ 사업내용 : 경기주택도시공사가 신축 주택을 매입하여 용인청년 1인 창조기업인에게 직‧주 혼합 소호(SOHO)형 주택을 주변시세의 30~50% 이하로 임대
