-어학&middot;한국사, 국가자격증 응시료 실비 및 교재비 지원', '21', '전남광주통합특별시 완도군', 19, 49, FALSE, '0043001', 0, 0, NULL, '시험 응시일 기준 미취업자(시험 응시 이후 취업 여부 무관)
 *사업자등록 중인 자는 신청 불가', NULL, '2025-01-01', '2025-12-10', FALSE),
