('20250106005400210053', '곡성군 청년, 신혼부부 주택자금 대출이자 지원사업', '보조금', '곡성군에 거주하는 청년 및 신혼부부에게 주택자금(전세, 매매) 대출이자 납부액 연 최대 100만 원씩 2년간 지원하는 사업', '곡성군에 거주하는 청년 및 신혼부부에게 주택자금(전세, 매매) 대출이자 납부액 연 최대 100만 원씩 2년간 지원
  1. 신청자격 (아래 가 ~ 마 요건을 모두 충족하여야 함)
    가. (주    소) 신청일 기준, 곡성군에 주소를 두고 6개월 이상 계속 거주
       - 곡성군 소재 주택을 전세&middot;매매하고, 그 주택에 주소를 두어야 함
       - 신혼부부의 경우 부부 모두 곡성군에 주소를 두고 거주
    나. (무 주 택) 본인 및 가구 구성원 모두가 무주택
       - 무주택이란 한국주택금융공사 등 대출심사를 받은 주택 외에 다른 주택(분양권 포함)을 소유하지 않은 것을 의미
    다. (사업대상) 주택자금(전세&middot;매매)용 대출을 받은 청년 또는 신혼부부
      - 청    년 : 만 19세 이상 49세 이하 청년
      - 신혼부부 : 최초 사업 신청일 기준, 부부 모두 만 19세 이상 49세 이하이고 혼인신고 이후 5년이 경과하지 않은 신혼부부
    라. (소득기준)
      - 청     년 : 가구소득 인정액이 기준중위소득 180% 이하인 자
      - 신혼부부 : 부부합산 연소득 8,000만원 이하
    마. (대상주택)
      - 주택가격 4억 원 이하, 전세 보증금 2억 5천만 원 이하인 관내 주택
      - 주거전용면적 100㎡이하
       ※ 주택법상의 단독&middot;다중&middot;다가구&middot;아파트&middot;다세대연립주택&middot;오피스텔', '11', '전남광주통합특별시 곡성군 인구정책과', 19, 49, FALSE, '0043003', 0, 0, '기준중위소득 180%이하(2024년 기준 1인가구 월 4,012,000원 이하) 청년, 부부합산 연소득 8천만원 이하 신혼부부', NULL, '가. 1가구 다주택 소유자(분양권 포함)
    나. 저소득층 주거급여 대상자
